body{margin:0;font-family:"PingFang SC","Microsoft YaHei",sans-serif;background:#f2f4f8;color:#1f2733}
header{background:#123a6d;color:#fff;padding:14px 32px;display:flex;align-items:center;justify-content:space-between}
.brand{font-size:20px;font-weight:600;letter-spacing:1px}
nav a{color:#d7e3f4;margin-left:22px;text-decoration:none;font-size:14px}
nav a:hover{color:#fff}
main{max-width:960px;margin:28px auto;padding:0 16px}
.notice{background:#fff8e6;border:1px solid #f0d48a;border-radius:6px;padding:16px 20px}
.notice h2{font-size:16px;margin:0 0 8px;color:#8a5a00}
.notice p{margin:4px 0;font-size:14px;line-height:1.7}
.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:24px}
.tile{background:#fff;border:1px solid #dde3ec;border-radius:8px;padding:20px;text-decoration:none;color:#1f2733}
.tile:hover{border-color:#2f6fb2}
.tile .t{font-size:15px;font-weight:600;margin-bottom:6px}
.tile .d{font-size:12px;color:#6b7787;line-height:1.6}
footer{max-width:960px;margin:32px auto 16px;padding:0 16px;font-size:12px;color:#8a93a3}

*{box-sizing:border-box}body{line-height:1.6}nav{display:flex;gap:22px}nav a{margin:0}a{color:#205d9c}h1{font-size:28px;line-height:1.35;margin-bottom:8px}h2{font-size:19px}h3{font-size:16px}.lead,.meta{color:#657386}.meta{font-size:13px}.panel{background:#fff;border:1px solid #dde3ec;border-radius:8px;padding:24px;margin-top:24px}.policy{white-space:pre-line;overflow-wrap:anywhere;font:inherit}.status{display:inline-block;border-radius:20px;color:#236544;background:#e9f6ed;padding:3px 10px;font-size:13px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:14px 10px;border-bottom:1px solid #e8edf3}th{color:#657386}.search{display:flex;gap:10px}input{padding:10px 12px;border:1px solid #bcc9db;border-radius:5px;font:inherit;min-width:0;flex:1}button{border:0;border-radius:5px;padding:10px 18px;background:#205d9c;color:white;font:inherit;cursor:pointer}.back{display:inline-block;margin-bottom:14px}.sr{position:absolute;left:-10000px}.meta a{color:inherit}pre{white-space:pre-wrap}article p{line-height:1.9}.empty{color:#657386;padding:18px 0}.help-list{padding-left:20px}@media(max-width:700px){header{padding:16px;display:block}.brand{font-size:18px}nav{flex-wrap:wrap;gap:10px 18px;margin-top:10px}nav a{font-size:13px}main{margin:20px auto}.tiles{grid-template-columns:1fr;gap:10px}.panel{padding:18px}h1{font-size:24px}table{font-size:12px}th,td{padding:10px 5px}.search{flex-wrap:wrap}}
